// Generated by Plume from the Zig type App: do not edit.

/** A Zig error from a binding: the error's name in `code`. */
export class PlumeError<Code extends string = string> extends Error {
  readonly code: Code;
  constructor(code: Code, message?: string) {
    super(message ?? code);
    this.name = "PlumeError";
    this.code = code;
  }
}

export interface Greeting {
  text: string;
  number: number;
}

export interface Progress {
  done: number;
  total: number;
}

export interface AppErrors {
  greet: "OutOfMemory";
  countTo: "Canceled";
}

export interface AppBindings {
  /** Fails with PlumeError<AppErrors["greet"]>. */
  greet(arg1: string): Greeting;
  /** Fails with PlumeError<AppErrors["countTo"]>. */
  countTo(arg1: number): Promise<number>;
}

// The page runtime: the window, dialogs, clipboard, screens and menus.
export interface PlumeSize { width: number; height: number; }
export interface PlumePosition { x: number; y: number; }
export interface PlumeRect { x: number; y: number; width: number; height: number; }
export interface PlumeScreen { bounds: PlumeRect; work_area: PlumeRect; scale: number; refresh_rate: number; primary: boolean; name: string; }
export type PlumeWindowState = "normal" | "minimized" | "maximized" | "fullscreen" | "hidden";
export interface PlumeWindowEvents { resized: PlumeSize; moved: PlumePosition; focus: boolean; state: PlumeWindowState; screen: null; "files-dropped": { paths: string[]; x: number; y: number }; }
export interface PlumeWindow {
  minimize(): void;
  maximize(): void;
  restore(): void;
  toggleMaximize(): void;
  /** As the user closing it: Zig's onClose handler may keep it open. */
  close(): void;
  center(): void;
  show(): void;
  hide(): void;
  focus(): void;
  setTitle(title: string): void;
  setSize(width: number, height: number): void;
  setMinSize(width: number, height: number): void;
  setMaxSize(width: number, height: number): void;
  setPosition(x: number, y: number): void;
  setResizable(resizable: boolean): void;
  setAlwaysOnTop(onTop: boolean): void;
  setFullscreen(fullscreen: boolean): void;
  size(): PlumeSize;
  position(): PlumePosition;
  state(): PlumeWindowState;
  screen(): PlumeScreen;
  /** The window as the user sees it (native layer included): a PNG file's bytes. */
  capture(): Promise<Uint8Array>;
  on<K extends keyof PlumeWindowEvents>(name: K, listener: (data: PlumeWindowEvents[K]) => void): () => void;
}
export interface PlumeFileFilter { name: string; extensions: string[]; }
export interface PlumeFileDialogOptions { title?: string; acceptLabel?: string; location?: string; filters?: PlumeFileFilter[]; multiple?: boolean; }
export interface PlumeMessageButton { id: number; label: string; default?: boolean; cancel?: boolean; }
export interface PlumeMessageOptions { kind?: "info" | "warning" | "error"; title?: string; message: string; buttons?: PlumeMessageButton[]; }
export interface PlumeDialogs {
  /** Existing files: their paths, empty if cancelled. */
  open(options?: PlumeFileDialogOptions): Promise<string[]>;
  /** Folders: their paths, empty if cancelled. */
  folder(options?: Omit<PlumeFileDialogOptions, "filters">): Promise<string[]>;
  /** A path to save to, or null if cancelled. */
  save(options?: Omit<PlumeFileDialogOptions, "multiple">): Promise<string | null>;
  /** The chosen button's id. */
  message(options: PlumeMessageOptions): Promise<number>;
}
export type PlumeMenuItem =
  | "separator"
  | { type?: "item"; id: string; label: string; accelerator?: string; enabled?: boolean }
  | { type: "checkbox"; id: string; label: string; accelerator?: string; checked?: boolean; enabled?: boolean }
  | { label: string; items: PlumeMenuItem[] };
export interface PlumeContextChoice { menu: string; id: string; data: string; }
export interface PlumeWindowOptions { title?: string; width?: number; height?: number; resizable?: boolean; frameless?: boolean; transparent?: boolean; url?: string; hidden?: boolean; }
export interface PlumeNotification { title: string; body?: string; tag?: string; actions?: string[]; }
export interface PlumeRelease { version: string; notes: string; url: string; signature_url: string; size: number; compressed: boolean; }
export interface PlumeDesktop {
  platform: "windows" | "linux";
  window: PlumeWindow;
  dialog: PlumeDialogs;
  clipboard: { readText(): string | null; writeText(text: string): void };
  screens(): PlumeScreen[];
  menu: {
    /** A popup menu at (x, y), CSS pixels: the chosen item's id, or null. */
    popup(items: PlumeMenuItem[], x: number, y: number): Promise<string | null>;
    /** The menu bar's items, Zig's popup menus and the tray's, by id. */
    on(listener: (id: string) => void): () => void;
    /** Items of Zig's context menus (app.setContextMenu), shown for elements marked data-plume-menu. */
    onContext(listener: (choice: PlumeContextChoice) => void): () => void;
  };
  app: {
    /** The program's arguments, its name first. */
    args(): string[];
    quit(): void;
    /** With the system: a web page in the browser, mailto: in the mail program. */
    openURL(url: string): void;
    /** A file or folder with the system's program for it. */
    openPath(path: string): void;
    startsAtLogin(): boolean;
    setStartAtLogin(enabled: boolean): void;
  };
  openURL(url: string): void;
  windows: {
    /** Another window: a page of the frontend ("settings.html") or a URL. */
    open(options?: PlumeWindowOptions): void;
  };
  notifications: {
    /** Up to three buttons (actions); the same tag replaces a notification still shown. */
    show(notification: PlumeNotification): void;
    remove(tag: string): void;
    /** action: -1 for the notification itself, else the button's index. */
    on(listener: (activated: { tag: string; action: number }) => void): () => void;
  };
  shortcuts: {
    /** Keys pressed anywhere ("Ctrl+Shift+K"); fails with plume:AlreadyExists if another application holds them. */
    register(name: string, accelerator: string): void;
    unregister(name: string): void;
    on(listener: (name: string) => void): () => void;
  };
  tray: {
    /** A click on the application's tray icon. */
    on(listener: (at: PlumePosition) => void): () => void;
  };
  updates: {
    /** The newer release on GitHub (plume.json's "update"), or null. */
    check(): Promise<PlumeRelease | null>;
    /** Downloads it, checks its signature and that it starts, puts it in place. */
    install(release: PlumeRelease): Promise<void>;
    /** Starts the new executable and quits. */
    restart(): void;
    /** The download's progress during install(), bytes (total 0 if unknown). */
    on(name: "progress", listener: (progress: { received: number; total: number }) => void): () => void;
  };
}

/** The events of App (its Events): names and data. */
export interface AppEvents {
  "progress": Progress;
}


const plume: any = (globalThis as any).Plume;

/** The window, dialogs, clipboard, screens and menus. */
export const Plume: PlumeDesktop = plume;

/** Events to and from Zig (app.emit, app.on) and between the page's listeners. */
export const Events = {
  on<K extends keyof AppEvents>(name: K, listener: (data: AppEvents[K]) => void): () => void { return plume.on(name, listener); },
  once<K extends keyof AppEvents>(name: K, listener: (data: AppEvents[K]) => void): () => void { return plume.once(name, listener); },
  off<K extends keyof AppEvents>(name: K, listener?: (data: AppEvents[K]) => void): void { plume.off(name, listener); },
  emit<K extends keyof AppEvents>(name: K, ...data: [AppEvents[K]] extends [void] ? [] : [data: AppEvents[K]]): void { plume.emit(name, ...data); },
};
const native: any = (globalThis as any).App;

function plumeError(error: unknown): unknown {
  if (error instanceof Error && error.message.startsWith("plume:")) {
    const [code, ...detail] = error.message.slice(6).split(": ");
    return new PlumeError(code, detail.length ? detail.join(": ") : code);
  }
  return error;
}

export const App: AppBindings = {
  greet(arg1) {
    try { return native.greet(arg1); } catch (error) { throw plumeError(error); }
  },
  countTo(arg1) {
    return native.countTo(arg1).catch((error: unknown) => { throw plumeError(error); });
  },
};
